:root {
  --ink: #24352d;
  --muted: #68776e;
  --card: #fffdf7;
  --pine: #35654e;
  --mint: #dcecdf;
  --coral: #f27d5d;
  --line: #d6e1d6;
  --warm: #fff1d8;
}

* {
  box-sizing: border-box;
}

.pass-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.pass-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 18px;
  background: var(--mint);
  border-bottom: 1px solid var(--line);
}

.paw-mark {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  place-items: center;
  font-size: 20px;
  background: var(--card);
  border-radius: 12px;
}

.title-block {
  min-width: 0;
  flex: 1;
}

.eyebrow,
.dog-detail,
.session-details dt {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: .07em;
  text-transform: uppercase;
}

h1 {
  margin: 3px 0 0;
  font-size: 19px;
  line-height: 1.1;
}

.level-badge {
  padding: 5px 8px;
  color: var(--pine);
  font-size: 11px;
  font-weight: 800;
  background: var(--warm);
  border-radius: 999px;
}

.pass-body {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 18px;
  padding: 17px 18px;
}

.dog-profile {
  display: flex;
  align-items: center;
  gap: 10px;
}

.dog-avatar {
  display: grid;
  width: 43px;
  height: 43px;
  flex: 0 0 auto;
  place-items: center;
  font-size: 23px;
  background: var(--warm);
  border-radius: 50%;
}

.dog-name {
  margin: 0 0 3px;
  font-size: 16px;
  font-weight: 800;
  line-height: 1;
}

.session-details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 0;
}

.session-details div {
  padding-left: 9px;
  border-left: 2px solid var(--mint);
}

.session-details dd {
  margin: 4px 0 0;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.2;
}

.pass-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  background: var(--card);
  border-top: 1px solid var(--line);
}

.check-status {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--pine);
  font-size: 12px;
  font-weight: 800;
}

.status-dot {
  width: 8px;
  height: 8px;
  background: var(--coral);
  border-radius: 50%;
}

button {
  padding: 8px 11px;
  color: var(--card);
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  background: var(--pine);
  border: 0;
  border-radius: 8px;
}
